class _ShardStream:
    """Lazy shard iterator holding the export's snapshot lock.

    Returned by :meth:`Chain.export_shards`. Each ``next`` produces one
    window-sized shard proof; the shared lock that pins the snapshot is
    held from the ``export_shards`` call until the stream is exhausted,
    closed or garbage collected, so every shard describes the same
    complete prefix no matter what other processes do meanwhile. The
    stream is its own iterator and a context manager, so a caller that
    stops early can release the snapshot deterministically.
    """

    def __init__(self, locked: Any, generator: Iterator[dict]):
        self._locked = locked
        self._generator = generator
        self._closed = False

    def __iter__(self) -> "_ShardStream":
        return self

    def __next__(self) -> dict:
        if self._closed:
            raise StopIteration
        try:
            return next(self._generator)
        except BaseException:
            # Exhaustion or a read failure both end the snapshot.
            self.close()
            raise

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        try:
            self._generator.close()
        finally:
            self._locked.__exit__(None, None, None)

    def __enter__(self) -> "_ShardStream":
        return self

    def __exit__(self, *exc_info: Any) -> bool:
        self.close()
        return False

    def __del__(self) -> None:
        try:
            self.close()
        except Exception:
            # Interpreter shutdown may have torn the lock module down.
            pass


def _cache_entry(
    records: int,
    stat: os.stat_result,
    parts: list[dict],
    states: dict[str, list],
    fold: str,
) -> dict:
    return {
        "records": records,
        "size": stat.st_size,
        "mtime_ns": stat.st_mtime_ns,
        "ctime_ns": stat.st_ctime_ns,
        "parts": parts,
        "fold": fold,
        "tenants": {tenant: list(state) for tenant, state in states.items()},
    }


# Empty fold seed and the per-line chaining. A fold is a byte-for-byte
# fingerprint of a unit's complete lines that can be extended over appended
# lines in O(new bytes) without re-reading the prefix: the cache stores the
# authenticated fold at the cached size, so a continued verify first proves
# every byte before that boundary is unchanged before trusting any cached
# cumulative state. A rewritten prefix (stale or recomputed digests, bytes
# edited behind preserved manifest windows) changes the fold and forces a
# full recompute. Chaining on the hex digest keeps this working under a
# sha256 stand-in that only exposes ``update``/``hexdigest``.
_FOLD_BLANK = hashlib.sha256(b"").hexdigest()


def _fold_accumulate(acc: str, lines: list[bytes]) -> str:
    for line in lines:
        acc = hashlib.sha256(acc.encode("ascii") + line).hexdigest()
    return acc


def _fold_lines(lines: list[bytes]) -> str:
    return _fold_accumulate(_FOLD_BLANK, lines)


def _extend_fold(fold: str, lines: list[bytes]) -> str:
    return _fold_accumulate(fold, lines)


def _split_whole_lines(raw: bytes) -> Optional[list[bytes]]:
    """Split bytes that are exactly a sequence of newline-ended lines.

    Returns the lines (each with its terminator) or None when the bytes end
    in a partial line -- which, at a cached-size boundary, means the prefix
    was rewritten and the boundary moved mid-line.
    """
    if raw == b"":
        return []
    if not raw.endswith(b"\n"):
        return None
    # Canonical JSON escapes embedded newlines, so a raw 0x0A is only ever a
    # record terminator.
    return [piece + b"\n" for piece in raw.split(b"\n")[:-1]]


def _fold_of_bytes(raw: bytes) -> str:
    lines = _split_whole_lines(raw)
    return _fold_lines(lines if lines is not None else [])


def _states_from(carried: dict) -> dict:
    return {
        tenant: list(state) for tenant, state in carried["tenants"].items()
    }


def _sha256(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def _iter_complete_lines(path: str) -> Iterator[bytes]:
    """Yield each complete newline-terminated line of a file, one at a time.

    A trailing piece without its newline is a crashed half-written line
    and is never a record. Memory tracks a single line, never the file.
    """
    with open(path, "rb") as handle:
        while True:
            line = handle.readline()
            if not line:
                return
            if not line.endswith(b"\n"):
                return
            yield line


def _index_runs(indices: list[int]) -> Iterator[tuple[int, int]]:
    """Group a sorted index list into contiguous ``[start, end)`` runs."""
    run_start = previous = indices[0]
    for index in indices[1:]:
        if index == previous + 1:
            previous = index
            continue
        yield run_start, previous + 1
        run_start = previous = index
    yield run_start, previous + 1


def _write_all(fd: int, data: bytes) -> None:
    """Write every byte of ``data`` to ``fd``, tolerating short writes."""
    view = memoryview(data)
    while view:
        written = os.write(fd, view)
        view = view[written:]

